SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:A_Romance_of_the_Air dbr:How_Moscha_Came_Back }
  ?film (dbo:director|dbp:director) ?director .
  ?director dbo:birthDate ?birthDate .
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(LANG(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(LANG(?directorLabel) = 'en') }
} ORDER BY ?film ?birthDate

SELECT DISTINCT ?earlierFilm ?earlierFilmLabel ?earlierDirector ?earlierDirectorLabel ?earlierBirthDate WHERE {
  VALUES (?fA ?fB) { (dbr:A_Romance_of_the_Air dbr:How_Moscha_Came_Back) }
  {
    ?fA (dbo:director|dbp:director) ?dA .
    ?dA dbo:birthDate ?bA .
    ?fB (dbo:director|dbp:director) ?dB .
    ?dB dbo:birthDate ?bB .
    FILTER(?bA < ?bB)
    BIND(?fA AS ?earlierFilm)
    BIND(?dA AS ?earlierDirector)
    BIND(?bA AS ?earlierBirthDate)
  }
  UNION
  {
    ?fA (dbo:director|dbp:director) ?dA .
    ?dA dbo:birthDate ?bA .
    ?fB (dbo:director|dbp:director) ?dB .
    ?dB dbo:birthDate ?bB .
    FILTER(?bB < ?bA)
    BIND(?fB AS ?earlierFilm)
    BIND(?dB AS ?earlierDirector)
    BIND(?bB AS ?earlierBirthDate)
  }
  OPTIONAL { ?earlierFilm rdfs:label ?earlierFilmLabel FILTER(lang(?earlierFilmLabel) = 'en') }
  OPTIONAL { ?earlierDirector rdfs:label ?earlierDirectorLabel FILTER(lang(?earlierDirectorLabel) = 'en') }
} LIMIT 10

